mapper.select:
SELECT m.id, m.nombre, m.fecha_nacimiento, m.genero, m.peso, m.color, m.imagen_url, m.especie_id, m.raza_id, m.cliente_id, m.created_at, m.updated_at, m.deleted, m.version, r.id AS raza_id, r.nombre AS raza_nombre, e.id AS especie_id, e.nombre AS especie_nombre FROM petcare.mascota m LEFT JOIN petcare.raza r ON r.id = m.raza_id AND r.deleted = FALSE LEFT JOIN petcare.especie e ON e.id = m.especie_id AND e.deleted = FALSE
m.deleted = FALSE AND m.nombre ILIKE '%' || #{nombre} '%'
ORDER BY m.created_at DESC LIMIT #{limit} OFFSET #{offset}
